  table(["", "м.р.", "ж.р."], [["1-й", "[[רִאשׁוֹן]]", "[[רִאשׁוֹנָה]]"], ["2-й", "[[שֵׁנִי]]", "[[שְׁנִיָּה]]"], ["3-й", "[[שְׁלִישִׁי]]", "[[שְׁלִישִׁית]]"], ["4-й", "[[רְבִיעִי]]", "[[רְבִיעִית]]"], ["5-й", "[[חֲמִישִׁי]]", "[[חֲמִישִׁית]]"], ["10-й", "[[עֲשִׂירִי]]", "[[עֲשִׂירִית]]"]]),
